"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$p = "C:'"\\Users\\hzq00\\.codex\\sessions\\2026\\08\\10\\rollout-2026-08-10T16-32-17-019feacd-184e-7472-9f11-ea364c22e595.jsonl\"
"'$types = @{}
$n = 0
$reader = [System.IO.File]::OpenText($p)
try {
  while (($line = $reader.ReadLine()) -ne $null) {
    $n++
    if ($line.Length -lt 5) { continue }
    try { $d = $line | ConvertFrom-Json -ErrorAction Stop } catch { continue }
    $t = $d.type
    $pt = $null
    if ($d.payload -and $d.payload.type) { $pt = $d.payload.type }
    $key = "$t|$pt"
    if ($types.ContainsKey($key)) { $types[$key]++ } else { $types[$key] = 1 }
  }
} finally { $reader.Close() }
Write-Output "total_lines=$n"
$types.GetEnumerator() | Sort-Object Value -Descending | Select-Object -First 30 | ForEach-Object { Write-Output ("{0} -> {1}" -f $_.Key, $_.Value) }'

